def cmp_semver(a, b):
    a_ver = a.split('+', 1)[0]
    b_ver = b.split('+', 1)[0]

    a_core_str, _, a_pre_str = a_ver.partition('-')
    b_core_str, _, b_pre_str = b_ver.partition('-')

    a_nums = tuple(map(int, a_core_str.split('.')))
    b_nums = tuple(map(int, b_core_str.split('.')))

    if a_nums != b_nums:
        return -1 if a_nums < b_nums else 1

    has_a_pre = bool(a_pre_str)
    has_b_pre = bool(b_pre_str)

    if not has_a_pre and not has_b_pre:
        return 0
    if has_a_pre and not has_b_pre:
        return -1
    if not has_a_pre and has_b_pre:
        return 1

    def parse_ids(s):
        ids = []
        for p in s.split('.'):
            try:
                ids.append((0, int(p)))
            except ValueError:
                ids.append((1, p))
        return ids

    a_ids = parse_ids(a_pre_str)
    b_ids = parse_ids(b_pre_str)

    if a_ids < b_ids:
        return -1
    elif a_ids > b_ids:
        return 1
    return 0
```

