import re

def gitignore_match(pattern, path):
    if not pattern:
        return False

    dir_only = pattern.endswith('/')
    if dir_only:
        pattern = pattern[:-1]

    anchored = pattern.startswith('/')
    if anchored:
        pattern = pattern[1:]

    match_inside = False
    if pattern.endswith('/**'):
        pattern = pattern[:-3]
        match_inside = True

    if pattern.startswith('**/'):
        pattern = pattern[3:]

    if '/' in pattern:
        anchored = True

    i, n = 0, len(pattern)
    res = []
    while i < n:
        c = pattern[i]
        if c == '*':
            res.append('[^/]*')
            i += 1
        elif c == '?':
            res.append('[^/]')
            i += 1
        elif c == '[':
            j = i + 1
            if j < n and pattern[j] in ('!', '^'):
                j += 1
            if j < n and pattern[j] == ']':
                j += 1
            while j < n and pattern[j] != ']':
                j += 1
            if j >= n:
                res.append(re.escape(c))
                i += 1
            else:
                cls = pattern[i:j+1]
                if cls.startswith('[!'):
                    cls = '[^' + cls[2:]
                res.append(cls)
                i = j + 1
        elif c in r'\.^$+{}()|':
            res.append('\\' + c)
            i += 1
        else:
            res.append(c)
            i += 1

    pat_re = ''.join(res)
    inner = '(?:/.*)?' if match_inside else ''

    if anchored:
        full_re = f'^{pat_re}{inner}$'
    else:
        full_re = f'(?:^|/){pat_re}{inner}$'

    if dir_only and not path.endswith('/'):
        return False

    match_path = path[:-1] if path.endswith('/') else path
    return bool(re.search(full_re, match_path))
