def parse_range(header, size):
    if not header or not header.lower().startswith('bytes='):
        return None

    spec = header[6:].strip()
    if not spec:
        return None

    ranges = []
    for part in spec.split(','):
        part = part.strip()
        if not part or '-' not in part:
            continue

        start_s, end_s = part.split('-', 1)
        try:
            if start_s == '':
                suffix = int(end_s)
                if suffix <= 0:
                    continue
                start = max(0, size - suffix)
                end = size - 1
            elif end_s == '':
                start = int(start_s)
                if start < 0:
                    continue
                end = size - 1
            else:
                start = int(start_s)
                end = int(end_s)
                if start < 0 or end < 0:
                    continue

            if start >= size or start > end:
                continue

            ranges.append((start, min(end, size - 1)))
        except ValueError:
            continue

    return ranges if ranges else None
