def unified_diff(a, b, context=3):
    m, n = len(a), len(b)
    dp = [[0] * (n + 1) for _ in range(m + 1)]
    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if a[i-1] == b[j-1]:
                dp[i][j] = dp[i-1][j-1] + 1
            else:
                dp[i][j] = max(dp[i-1][j], dp[i][j-1])

    matches = []
    i, j = m, n
    while i > 0 and j > 0:
        if a[i-1] == b[j-1]:
            matches.append((i-1, j-1))
            i -= 1
            j -= 1
        elif dp[i-1][j] >= dp[i][j-1]:
            i -= 1
        else:
            j -= 1
    matches.reverse()

    ops = []
    ai, bi = 0, 0
    for mi, mj in matches:
        while ai < mi:
            ops.append(('-', a[ai]))
            ai += 1
        while bi < mj:
            ops.append(('+', b[bi]))
            bi += 1
        ops.append((' ', a[ai]))
        ai += 1
        bi += 1
    while ai < m:
        ops.append(('-', a[ai]))
        ai += 1
    while bi < n:
        ops.append(('+', b[bi]))
        bi += 1

    change_indices = [i for i, (op, _) in enumerate(ops) if op != ' ']
    if not change_indices:
        return []

    blocks = []
    start = prev = change_indices[0]
    for idx in change_indices[1:]:
        if idx != prev + 1:
            blocks.append((start, prev))
            start = idx
        prev = idx
    blocks.append((start, prev))

    expanded = [(max(0, s - context), min(len(ops) - 1, e + context)) for s, e in blocks]

    merged = [expanded[0]]
    for s, e in expanded[1:]:
        ps, pe = merged[-1]
        if s <= pe + 1:
            merged[-1] = (ps, max(pe, e))
        else:
            merged.append((s, e))

    result = []
    curr_a, curr_b = 1, 1
    op_idx = 0
    for s, e in merged:
        while op_idx < s:
            op, _ = ops[op_idx]
            if op != '+': curr_a += 1
            if op != '-': curr_b += 1
            op_idx += 1

        hunk_ops = ops[s:e+1]
        alen = sum(1 for op, _ in hunk_ops if op != '+')
        blen = sum(1 for op, _ in hunk_ops if op != '-')

        result.append(f"@@ -{curr_a},{alen} +{curr_b},{blen} @@")
        for op, line in hunk_ops:
            result.append(f"{op}{line}")

    return result
