import collections

class LFUCache:
    def __init__(self, capacity):
        self.capacity = capacity
        self.key_val = {}
        self.key_freq = {}
        self.freq_keys = {}
        self.min_freq = 0

    def get(self, key):
        if key not in self.key_val:
            return -1
        self._update(key)
        return self.key_val[key]

    def put(self, key, value):
        if self.capacity <= 0:
            return
        if key in self.key_val:
            self.key_val[key] = value
            self._update(key)
        else:
            if len(self.key_val) == self.capacity:
                min_bucket = self.freq_keys[self.min_freq]
                evicted_key, _ = min_bucket.popitem(last=False)
                del self.key_val[evicted_key]
                del self.key_freq[evicted_key]

            self.key_val[key] = value
            self.key_freq[key] = 1
            if 1 not in self.freq_keys:
                self.freq_keys[1] = collections.OrderedDict()
            self.freq_keys[1][key] = None
            self.min_freq = 1

    def _update(self, key):
        freq = self.key_freq[key]
        del self.freq_keys[freq][key]
        if not self.freq_keys[freq]:
            del self.freq_keys[freq]
            if self.min_freq == freq:
                self.min_freq += 1

        self.key_freq[key] = freq + 1
        if freq + 1 not in self.freq_keys:
            self.freq_keys[freq + 1] = collections.OrderedDict()
        self.freq_keys[freq + 1][key] = None
