import heapq

def topk(stream, k):
    heap = []
    for idx, (val, label) in enumerate(stream):
        if len(heap) < k:
            heapq.heappush(heap, (val, idx, label))
        elif val > heap[0][0]:
            heapq.heapreplace(heap, (val, idx, label))
    return [(v, l) for v, i, l in sorted(heap, key=lambda x: (-x[0], x[1]))]
