def next_fire(expr, after):
    parts = expr.split()
    if len(parts) != 5:
        raise ValueError("Cron expression must have exactly 5 fields")

    min_f, hour_f, dom_f, month_f, dow_f = parts

    def parse_field(field_str, min_val, max_val):
        values = set()
        for part in field_str.split(','):
            if '/' in part:
                base, step_str = part.split('/', 1)
                try:
                    step = int(step_str)
                except ValueError:
                    raise ValueError(f"Invalid step in {part}")
                if step <= 0:
                    raise ValueError("Step must be positive")
                if base == '*':
                    start, end = min_val, max_val
                elif '-' in base:
                    a_str, b_str = base.split('-', 1)
                    try:
                        start, end = int(a_str), int(b_str)
                    except ValueError:
                        raise ValueError(f"Invalid range {base}")
                else:
                    try:
                        val = int(base)
                    except ValueError:
                        raise ValueError(f"Invalid value {base}")
                    if not (min_val <= val <= max_val):
                        raise ValueError(f"Value {val} out of range")
                    start, end = val, val
            elif '-' in part:
                a_str, b_str = part.split('-', 1)
                try:
                    start, end = int(a_str), int(b_str)
                except ValueError:
                    raise ValueError(f"Invalid range {part}")
                step = 1
            elif part == '*':
                start, end = min_val, max_val
                step = 1
            else:
                try:
                    val = int(part)
                except ValueError:
                    raise ValueError(f"Invalid value {part}")
                if not (min_val <= val <= max_val):
                    raise ValueError(f"Value {val} out of range")
                values.add(val)
                continue

            if not (min_val <= start <= end <= max_val):
                raise ValueError(f"Range {start}-{end} invalid or out of bounds")

            for v in range(start, end + 1, step):
                values.add(v)
        return values

    mins = parse_field(min_f, 0, 59)
    hours = parse_field(hour_f, 0, 23)
    doms = parse_field(dom_f, 1, 31)
    months = parse_field(month_f, 1, 12)
    dows = parse_field(dow_f, 0, 6)

    if not mins or not hours or not doms or not months or not dows:
        raise ValueError("Parsed field resulted in empty set")

    sorted_months = sorted(months)
    sorted_hours = sorted(hours)
    sorted_mins = sorted(mins)
    first_month = min(months)

    dom_is_star = (dom_f == '*')
    dow_is_star = (dow_f == '*')

    dt = after.replace(second=0, microsecond=0)
    if dt <= after:
        dt += timedelta(minutes=1)

    while True:
        if dt.month not in months:
            next_m = None
            for m in sorted_months:
                if m > dt.month:
                    next_m = m
                    break
            if next_m is not None:
                dt = dt.replace(year=dt.year, month=next_m, day=1, hour=0, minute=0)
            else:
                dt = dt.replace(year=dt.year + 1, month=first_month, day=1, hour=0, minute=0)
            continue

