        if dom_is_star and dow_is_star:
            day_match = True
        elif dom_is_star:
            day_match = (cron_dow in dows)
        elif dow_is_star:
            day_match = (dt.day in doms)
        else:
            day_match = (dt.day in doms) or (cron_dow in dows)

        if not day_match:
            dt += timedelta(days=1)
            dt = dt.replace(hour=0, minute=0)
            continue

        if dt.hour not in hours:
            next_h = None
            for h in sorted_hours:
                if h > dt.hour:
                    next_h = h
                    break
            if next_h is not None:
                dt = dt.replace(hour=next_h, minute=0)
            else:
                dt += timedelta(days=1)
                dt = dt.replace(hour=0, minute=0)
            continue

        if dt.minute not in mins:
