class RollbackDSU:
    def __init__(self, n):
        self.parent = list(range(n))
        self.size = [1] * n
        self.history = []
        self._components = n

    def find(self, x):
        while x != self.parent[x]:
            x = self.parent[x]
        return x

    def union(self, a, b):
        ra = self.find(a)
        rb = self.find(b)
        if ra == rb:
            return False
        if self.size[ra] < self.size[rb]:
            ra, rb = rb, ra
        self.history.append((rb, self.parent[rb], ra, self.size[ra]))
        self.parent[rb] = ra
        self.size[ra] += self.size[rb]
        self._components -= 1
        return True

    def snapshot(self):
        return len(self.history)

    def rollback(self, token):
        while len(self.history) > token:
            child, old_parent, root, old_size = self.history.pop()
            self.parent[child] = old_parent
            self.size[root] = old_size
            self._components += 1

    def components(self):
        return self._components
