    memo = {}
    def _copy(o):
        if not isinstance(o, (dict, list, set, tuple)):
            return o
        obj_id = id(o)
        if obj_id in memo:
            return memo[obj_id]

        if isinstance(o, dict):
            new_obj = {}
            memo[obj_id] = new_obj
            for k, v in o.items():
                new_obj[_copy(k)] = _copy(v)
            return new_obj
