def to_base(n, alphabet):
    if n == 0:
        return alphabet[0]
    neg = n < 0
    n = abs(n)
    base = len(alphabet)
    digits = []
    while n > 0:
        digits.append(alphabet[n % base])
        n //= base
    if neg:
        digits.append('-')
    return ''.join(reversed(digits))

def from_base(s, alphabet):
    if not s:
        raise ValueError("Empty string")
    base = len(alphabet)
    char_to_val = {c: i for i, c in enumerate(alphabet)}

    neg = False
    start = 0
    if s[0] == '-':
        neg = True
        start = 1

    result = 0
    for i in range(start, len(s)):
        char = s[i]
        if char not in char_to_val:
            raise ValueError(f"Character '{char}' not in alphabet")
        result = result * base + char_to_val[char]

    return -result if neg else result
