import heapq

def shortest_path(graph, src, dst):
    if src == dst:
        return (0, [src])

    dist = {src: (0, 0)}
    parent = {src: None}
    heap = [(0, 0, src)]

    while heap:
        cost, edges, u = heapq.heappop(heap)

        if u in dist and (cost, edges) > dist[u]:
            continue

        if u == dst:
            path = []
            curr = dst
            while curr is not None:
                path.append(curr)
                curr = parent[curr]
            return (cost, path[::-1])

        for v, w in graph.get(u, []):
            new_cost = cost + w
            new_edges = edges + 1

            prev = dist.get(v)
            if prev is None or (new_cost, new_edges) < prev:
                dist[v] = (new_cost, new_edges)
                parent[v] = u
                heapq.heappush(heap, (new_cost, new_edges, v))
            elif prev and (new_cost, new_edges) == prev:
                # Reconstruct existing path for v
                p_v = []
                node = v
                while node is not None:
                    p_v.append(node)
                    node = parent[node]
                p_v.reverse()

                # Reconstruct new path via u
                p_u = []
                node = u
                while node is not None:
                    p_u.append(node)
                    node = parent[node]
                p_u.reverse()
                p_new = p_u + [v]

                if p_new < p_v:
                    dist[v] = (new_cost, new_edges)
                    parent[v] = u
                    heapq.heappush(heap, (new_cost, new_edges, v))

    return (None, [])
