import heapq

def topo_lex(graph):
    in_degree = {}
    for u in graph:
        if u not in in_degree:
            in_degree[u] = 0
        for v in graph[u]:
            in_degree[v] = in_degree.get(v, 0) + 1

    heap = [n for n in in_degree if in_degree[n] == 0]
    heapq.heapify(heap)

    result = []
    while heap:
        u = heapq.heappop(heap)
        result.append(u)
        for v in graph.get(u, []):
            in_degree[v] -= 1
            if in_degree[v] == 0:
                heapq.heappush(heap, v)

    return result if len(result) == len(in_degree) else None
