function deepEqual(a, b) {
  const seen = new Map();
  return compare(a, b, seen);
}

function getEnumerableKeys(obj) {
  return [
    ...Object.keys(obj),
    ...Object.getOwnPropertySymbols(obj).filter(s => obj.propertyIsEnumerable(s))
  ];
}

function compareIterable(a, b, seen) {
  const used = new Set();
  const bItems = [...b];
  for (const itemA of a) {
    let found = false;
    for (let i = 0; i < bItems.length; i++) {
      if (used.has(i)) continue;
      if (compare(itemA, bItems[i], seen)) {
        used.add(i);
        found = true;
        break;
      }
    }
    if (!found) return false;
  }
  return true;
}

function compare(a, b, seen) {
  if (a === b) return true;
  if (typeof a !== typeof b || a === null || b === null) {
    return Number.isNaN(a) && Number.isNaN(b);
  }
  if (typeof a !== 'object') return false;

  const seenB = seen.get(a);
  if (seenB) return seenB.has(b);

  const newSeenB = new Set();
  newSeenB.add(b);
  seen.set(a, newSeenB);

  const tagA = Object.prototype.toString.call(a);
  const tagB = Object.prototype.toString.call(b);
  if (tagA !== tagB) return false;

  switch (tagA) {
    case '[object Date]':
      return a.getTime() === b.getTime();
    case '[object RegExp]':
      return a.source === b.source && a.flags === b.flags;
    case '[object Map]':
      if (a.size !== b.size) return false;
      return compareIterable(a, b, seen);
    case '[object Set]':
      if (a.size !== b.size) return false;
      return compareIterable(a, b, seen);
    default:
      const keysA = getEnumerableKeys(a);
      const keysBSet = new Set(getEnumerableKeys(b));
      if (keysA.length !== keysBSet.size) return false;
      for (const key of keysA) {
        if (!keysBSet.has(key)) return false;
        if (!compare(a[key], b[key], seen)) return false;
      }
      return true;
  }
}

module.exports = deepEqual;
