module.exports = function pLimit(n) {
  let queue = [];
  let active = 0;

  const next = () => {
    if (queue.length > 0 && active < n) {
      active++;
      queue.shift()();
    }
  };

  return function limit(fn) {
    return new Promise((resolve, reject) => {
      const run = () => {
        fn()
          .then(resolve)
          .catch(reject)
          .finally(() => {
            active--;
            next();
          });
      };

      if (active < n) {
        active++;
        run();
      } else {
        queue.push(run);
      }
    });
  };
};
