module.exports = function debounce(fn, wait, options = {}) {
  let timerId = null;
  let lastArgs = null;
  let lastThis = null;
  let result = undefined;
  let leadingCalled = false;
  let calledAfterLeading = false;

  const leading = !!options.leading;
  const trailing = options.trailing !== false;

  const trailingEdge = () => {
    timerId = null;
    if (trailing) {
      if (!(leading && leadingCalled && !calledAfterLeading)) {
        result = fn.apply(lastThis, lastArgs);
      }
    }
  };

