    lastThis = this;
    if (!timerId) {
      leadingCalled = false;
      calledAfterLeading = false;
      if (leading) {
        result = fn.apply(lastThis, lastArgs);
        leadingCalled = true;
      }
      timerId = setTimeout(trailingEdge, wait);
    } else {
      clearTimeout(timerId);
      calledAfterLeading = true;
      timerId = setTimeout(trailingEdge, wait);
    }
    return result;
