    this.listeners = new Map();
    this.nextId = 0;
  }

  on(event, fn) {
    const id = this.nextId++;
    const listener = { id, fn, once: false };
    if (!this.listeners.has(event)) this.listeners.set(event, []);
    this.listeners.get(event).push(listener);
    return () => {
      const list = this.listeners.get(event);
      if (list) {
        for (let i = 0; i < list.length; i++) {
          if (list[i].id === id) {
            list.splice(i, 1);
            break;
          }
        }
      }
    };
  }

  once(event, fn) {
    const id = this.nextId++;
    const listener = { id, fn, once: true };
    if (!this.listeners.has(event)) this.listeners.set(event, []);
    this.listeners.get(event).push(listener);
    return () => {
      const list = this.listeners.get(event);
      if (list) {
        for (let i = 0; i < list.length; i++) {
          if (list[i].id === id) {
            list.splice(i, 1);
            break;
          }
        }
      }
    };
  }

  off(event, fn) {
    const list = this.listeners.get(event);
    if (!list) return;
    for (let i = 0; i < list.length; i++) {
      if (list[i].fn === fn) {
        list.splice(i, 1);
        break;
      }
    }
  }

  emit(event, ...args) {
    const list = this.listeners.get(event);
    if (!list || list.length === 0) return 0;

    const snapshot = [...list];
    let invokedCount = 0;
    let firstError = null;

    for (const listener of snapshot) {
      if (!list.includes(listener)) continue;

      if (listener.once) {
        const idx = list.indexOf(listener);
        if (idx !== -1) list.splice(idx, 1);
      }

      try {
        listener.fn(...args);
        invokedCount++;
      } catch (err) {
        if (!firstError) firstError = err;
        invokedCount++;
      }
    }

    if (firstError) throw firstError;
    return invokedCount;
  }
}

