  let text = '';
  const valuesArr = [];
  let nextPlaceholder = 1;

  for (let i = 0; i < strings.length; i++) {
    text += strings[i];
    if (i < values.length) {
      const val = values[i];
      if (typeof val === 'object' && val !== null && 'text' in val && 'values' in val) {
        text += val.text.replace(/\$(\d+)/g, (_, num) => {
          valuesArr.push(val.values[num - 1]);
          return `$${nextPlaceholder++}`;
        });
      } else if (Array.isArray(val)) {
        const placeholders = [];
        for (const item of val) {
          placeholders.push(`$${nextPlaceholder++}`);
          valuesArr.push(item);
        }
        text += `(${placeholders.join(', ')})`;
      } else {
        valuesArr.push(val);
        text += `$${nextPlaceholder++}`;
      }
    }
  }

  return { text, values: valuesArr };
}

