function memoize(fn, keyFn) {
  let calls = 0;
  const keyedCache = new Map();
  let objCache = new WeakMap();
  let primCache = new Map();

  const memoized = function(...args) {
    let cache, key;

    if (keyFn) {
      key = keyFn(...args);
      cache = keyedCache;
    } else if (args.length === 1) {
      const arg = args[0];
      if (typeof arg === 'object' && arg !== null) {
        key = arg;
        cache = objCache;
      } else {
        key = arg;
        cache = primCache;
      }
    } else {
      key = args.join('\0');
      cache = primCache;
    }

    if (cache.has(key)) return cache.get(key);

    calls++;
    try {
      const result = fn(...args);
      cache.set(key, result);
      return result;
    } catch (err) {
      throw err;
    }
  };

  Object.defineProperty(memoized, 'calls', { get: () => calls });
  memoized.clear = function() {
    keyedCache.clear();
    objCache = new WeakMap();
    primCache.clear();
  };

  return memoized;
}

module.exports = memoize;
