  function subscribe(fn) {
    if (!subscribers.includes(fn)) {
      subscribers.push(fn);
    }
    return () => {
      const idx = subscribers.indexOf(fn);
      if (idx !== -1) {
        subscribers.splice(idx, 1);
      }
    };
  }

  return { getState, dispatch, subscribe };
}
