function toposortTasks(tasks) {
    const visited = new Set();
    const recStack = new Set();

    function validate(name) {
        if (recStack.has(name)) throw new Error("cycle detected");
        if (visited.has(name)) return;
        visited.add(name);
        recStack.add(name);
        for (const dep of tasks[name].deps) {
            if (!(dep in tasks)) throw new Error(`Unknown dependency: ${dep}`);
            validate(dep);
        }
        recStack.delete(name);
    }

    try {
        for (const name in tasks) {
            if (!visited.has(name)) validate(name);
        }
    } catch (e) {
        return Promise.reject(e);
    }

    const results = {};
    const taskPromises = {};

    function getPromise(name) {
        if (taskPromises[name]) return taskPromises[name];
        taskPromises[name] = Promise.all(tasks[name].deps.map(d => getPromise(d)))
            .then(() => {
                const depValues = {};
                for (const d of tasks[name].deps) depValues[d] = results[d];
                return tasks[name].run(depValues);
            });

        taskPromises[name].then(res => results[name] = res).catch(() => {});
        return taskPromises[name];
    }

    for (const name in tasks) getPromise(name);

    return Promise.allSettled(Object.values(taskPromises))
        .then(settled => {
            const rejections = settled.filter(s => s.status === 'rejected');
            if (rejections.length > 0) throw rejections[0].reason;
            return results;
        });
}

module.exports = toposortTasks;
