type ExtractParams<T extends string> = T extends `${infer _}:${infer Param}/${infer Rest}`
  ? Param | ExtractParams<Rest>
  : T extends `${infer _}:${infer Param}`
    ? Param
    : never;

type RouteFn<T extends string> = [ExtractParams<T>] extends [never]
  ? () => string
  : (params: Record<ExtractParams<T>, string>) => string;

export function defineRoutes<R extends Record<string, string>>(routes: R): {
  [K in keyof R]: RouteFn<R[K]>;
} {
  const result = {} as Partial<{ [K in keyof R]: RouteFn<R[K]> }>;
  for (const key of Object.keys(routes) as Array<keyof R>) {
    const path = routes[key];
    const matches = path.match(/:(\w+)/g);
    if (!matches) {
      result[key] = () => path;
    } else {
      const paramNames = matches.map(m => m.slice(1));
      result[key] = (params: Record<string, string>) => {
        let res = path;
        for (const p of paramNames) {
          res = res.replace(`:${p}`, params[p]);
        }
        return res;
      };
    }
  }
  return result as any;
}
