  ? T
  : T extends object
    ? { [K in keyof T]?: DeepPartial<T[K]> }
    : T;

export function applyPatch<T>(base: T, patch: DeepPartial<T>): T {
  if (typeof base !== 'object' || base === null) return base;
  const result = { ...base } as T;
  for (const key of Object.keys(patch)) {
    const pVal = (patch as any)[key];
    if (pVal === undefined) continue;
    const bVal = (result as any)[key];
    if (typeof pVal === 'object' && pVal !== null && !Array.isArray(pVal) &&
        typeof bVal === 'object' && bVal !== null && !Array.isArray(bVal)) {
      (result as any)[key] = applyPatch(bVal, pVal);
    } else {
      (result as any)[key] = pVal;
    }
  }
  return result;
}
